package com.example.domain.model.i18n

internal object DuaUz1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Uyg'onish", "Bizni o'ldirgandan (uxlatgandan) so'ng qayta tiriltirgan Allohga hamd bo'lsin, qaytish ham Unga.", "Uyg'ongandan so'ng darhol Allohga shukr sifatida aytiladi.", "Payg'ambar ﷺ uyg'onganda buni aytar edilar — kunni shukr va oxiratni eslash bilan boshlash."),
        "dua_leaving_home" to DuaText("Uydan chiqish", "Alloh nomi bilan; men Allohga tavakkal qildim. Kuch-quvvat faqat Alloh bilandir.", "Uydan chiqayotganda Alloh himoyasi uchun aytiladi.", "Farishtalar: 'Sen hidoyat qilinding, g'amxo'rlik qilindi va himoya qilindingʻ, deydi, shayton esa uzoqlashadi."),
        "dua_anxiety_distress" to DuaText("Xavotir va g'am duosi", "Ey Alloh, xavotir va g'amdan, ojizlik va dangasalikdan, baxillik va qo'rqoqlikdan, qarz yukidan va odamlarning zulmidan Senga sig'inaman.", "G'am, xavotir, qarz yoki ruhiy bosim paytida.", "Payg'ambar ﷺ buni tez-tez o'qir edilar — g'am, dangasalik va qarzdan panoh."),
        "dua_sayyidul_istighfar" to DuaText("Istig'forning sardori", "Ey Alloh, Sen mening Rabbimsan; Sendan boshqa haq iloh yo'q. Sen meni yaratding, men Sening bandangman, imkon qadar ahdimga va va'dimga sodiqman. Qilgan yomonligimdan Senga sig'inaman. Menga bergan ne'matingni tan olaman, gunohimni ham tan olaman, meni kechir, chunki gunohlarni faqat Sen kechirasan.", "Ertalab va kechqurun aytiladi — Payg'ambar ﷺ o'rgatgan eng yaxshi tavba duosi.", "Kim buni kechqurun ishonch bilan aytib, o'sha kechasi vafot etsa, jannatga kiradi; ertalab ham xuddi shunday."),
        "dua_parents" to DuaText("Ota-onalar uchun duo", "Rabbim, ular meni bolaligimda tarbiyalaganidek, ikkalasiga ham rahm qil.", "Ota-onaning bolalikdagi g'amxo'rligiga javoban Qur'ondagi duo.", "Alloh O'zi bizga ota-onamiz uchun shu duoni qilishni buyurgan."),
        "dua_entering_mosque" to DuaText("Masjidga kirish", "Ey Alloh, menga rahmating eshiklarini och.", "Masjidga o'ng oyoq bilan kirayotganda aytiladi.", "Payg'ambar ﷺ masjidga kirish uchun shu duoni o'rgatganlar."),
        "dua_morning_asbahna" to DuaText("Ertalabki zikr", "Tong otdi, barcha mulk Allohnikidir, barcha hamd Allohgadir. Allohdan boshqa haq iloh yo'q, U yagona, sherigi yo'q. Mulk ham, hamd ham Unikidir, U har narsaga qodirdir.", "Ertalab o'qiladigan sunnat duosi.", "Kun Allohning mulki va yagonaligini tan olish bilan boshlanadi."),
        "dua_evening_amsayna" to DuaText("Kechki zikr", "Kech kirdi, barcha mulk Allohnikidir, barcha hamd Allohgadir. Allohdan boshqa haq iloh yo'q, U yagona, sherigi yo'q. Mulk ham, hamd ham Unikidir, U har narsaga qodirdir.", "Kechqurun o'qiladigan sunnat duosi.", "Tun Allohning mulki va yagonaligini tan olish bilan boshlanadi."),
        "dua_before_sleep" to DuaText("Uxlashdan oldin", "Ey Alloh, Sening noming bilan o'laman (uxlayman) va tirilaman (uyg'onaman).", "Yotoqqa yotgandan keyin aytiladi.", "Payg'ambar ﷺ uxlashdan oldin buni aytar edilar."),
        "dua_travel" to DuaText("Safar duosi", "Buni bizga bo'ysundirgan Zot pokdir, biz buni o'zimiz uddalay olmagan bo'lardik, albatta biz Rabbimizga qaytuvchimiz.", "Ulovga o'tirgandan so'ng, uch marta Allohu akbar deyilgach aytiladi.", "Himoya va barakot uchun sunnat safar duosi."),
        "dua_ayatul_kursi" to DuaText("Namozdan keyingi Oyatul Kursiy", "Alloh — Undan boshqa haq iloh yo'q, tirik, hamma narsani boshqaruvchi. Uni na mudroq, na uyqu tutmaydi. Osmonlaru yerdagi barcha narsa Unikidir. Uning ruxsatisiz kim Uning oldida shafoat qila oladi? U ularning oldidagi va ortidagi narsalarni biladi. Ular Uning ilmidan U xohlagan narsadan boshqasini qamrab ololmaydilar. Uning Kursisi osmonlaru yerni qamrab olgan, ularni saqlash Uni charchatmaydi. U Oliy va Buyukdir.", "Har bir farz namozdan keyin va uxlashdan oldin.", "Har farz namozdan keyin buni o'qigan kishini jannatga faqat o'lim to'sadi; uxlashdan oldin ertalabgacha himoyalanadi."),
        "dua_hasbunallah" to DuaText("Alloh bizga kifoya", "Alloh bizga kifoya, U eng yaxshi vakil.", "Dushmandan qo'rqqanda yoki katta xavf paytida.", "Ibrohim (a.s.) olovga tashlanganda buni aytgan, Payg'ambar ﷺ ham xavf paytida aytar edilar."),
        "dua_entering_home" to DuaText("Uyga kirish", "Alloh nomi bilan (uyga kiraman).", "Uyga kirishda Alloh nomini aytish va salom berish.", "Kirishda va ovqatlanishda Alloh eslansa, shayton: bu yerda tunash joyi ham, kechki ovqat ham yo'q, deydi."),
        "dua_yunus" to DuaText("Yunus payg'ambar (a.s.) duosi", "Sendan boshqa haq iloh yo'q, Sen pok Zotsan; darhaqiqat, men zolimlardan bo'ldim.", "Yunus payg'ambarning baliq qornidagi duosi — har qanday qiyinchilik uchun.", "Har qanday musulmon biror ishda shu duoni qilsa, Alloh javob beradi."),
        "dua_karb" to DuaText("Katta qiyinchilik duosi", "Allohdan boshqa haq iloh yo'q, Buyuk, Halim. Allohdan boshqa haq iloh yo'q, Buyuk Arshning Rabbi. Allohdan boshqa haq iloh yo'q, osmonlar Rabbi, yer Rabbi va Karamli Arsh Rabbi.", "Katta qiyinchilik va mashaqqat paytida aytiladi.", "Payg'ambar ﷺ qiyinchilik paytida buni aytar edilar."),
    )
}
